import app from 'flarum/common/app';
import { flat } from './jsonapi';
// Giveaways and categories are JSON:API resources; the pages use them flat, with a numeric id.

function one(res) {
  return {
    data: flat(res.data)
  };
}
function base() {
  return app.forum.attribute('apiUrl') + '/giveaways';
}
export function listGiveaways() {
  return app.request({
    method: 'GET',
    url: base()
  }).then(res => ({
    data: res.data.map(r => flat(r)),
    meta: res.meta
  }));
}

/** Giveaways by slug (or old id), for the cards links in posts become; at most 20 a request. */
export function giveawaysBySlug(keys) {
  return app.request({
    method: 'GET',
    url: base(),
    params: {
      filter: {
        slug: keys.join(',')
      }
    }
  }).then(res => res.data.map(r => flat(r)));
}
export function showGiveaway(idOrSlug) {
  return app.request({
    method: 'GET',
    url: `${base()}/${encodeURIComponent(idOrSlug)}`
  }).then(one);
}
export function enterGiveaway(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/enter`
  }).then(one);
}
export function drawGiveaway(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/draw`
  }).then(one);
}

/** `answer` is the skill-testing answer, required only when the giveaway sets one. */
export function claimGiveaway(id, answer) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/claim`,
    body: {
      answer: answer ?? ''
    }
  }).then(one);
}
export function listEntrants(id, offset = 0) {
  return app.request({
    method: 'GET',
    url: `${base()}/${id}/entrants`,
    params: {
      page: {
        offset
      }
    }
  });
}
export function deleteGiveaway(id) {
  return app.request({
    method: 'DELETE',
    url: `${base()}/${id}`
  });
}
export function saveGiveaway(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${base()}/${id}` : base(),
    body: {
      data: {
        type: 'giveaways',
        ...(id ? {
          id: String(id)
        } : {}),
        attributes
      }
    }
  }).then(one);
}
function catBase() {
  return app.forum.attribute('apiUrl') + '/giveaway-categories';
}
export function listCategories() {
  return app.request({
    method: 'GET',
    url: catBase()
  }).then(res => ({
    data: res.data.map(r => flat(r))
  }));
}
export function saveCategory(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${catBase()}/${id}` : catBase(),
    body: {
      data: {
        type: 'giveaway-categories',
        ...(id ? {
          id: String(id)
        } : {}),
        attributes
      }
    }
  }).then(one);
}
export function deleteCategory(id) {
  return app.request({
    method: 'DELETE',
    url: `${catBase()}/${id}`
  });
}
flarum.reg.add('ernestdefoe-giveaways', 'common/api', { listGiveaways: listGiveaways,giveawaysBySlug: giveawaysBySlug,showGiveaway: showGiveaway,enterGiveaway: enterGiveaway,drawGiveaway: drawGiveaway,claimGiveaway: claimGiveaway,listEntrants: listEntrants,deleteGiveaway: deleteGiveaway,saveGiveaway: saveGiveaway,listCategories: listCategories,saveCategory: saveCategory,deleteCategory: deleteCategory, });